import {
  RiAlarmLine, RiArrowRightSLine, RiCalendarEventLine, RiCheckLine, RiHistoryLine,
  RiMapPinLine, RiPauseLine, RiPlayLine, RiShieldCheckLine, RiTimeLine,
  RiUserLine, RiTeamLine, RiFileChartLine, RiEditLine, RiInformationLine,
} from "@remixicon/react";
import { Avatar } from "@/components/base/avatar/avatar";
import { Chip, type ChipColor } from "@/components/base/badges/chip";
import { Button } from "@/components/base/buttons/button";
import { Checkbox } from "@/components/base/checkbox/checkbox";
import { Input } from "@/components/base/input/input";
import { Modal, ModalBody, ModalFooter, ModalHeader } from "@/components/base/modal/modal";
import { Select, SelectItem } from "@/components/base/select/select";
